use aegisguard::{audit, evaluate, EvaluateRequest};
use tokio::{io::{AsyncBufReadExt, AsyncWriteExt, BufReader}, net::{UnixListener, UnixStream}};
use std::{env, fs, path::PathBuf};
async fn client(stream: UnixStream, audit_path: PathBuf) { let (r, mut w) = stream.into_split(); let mut lines = BufReader::new(r).lines(); while let Ok(Some(line)) = lines.next_line().await { let out = serde_json::from_str::<EvaluateRequest>(&line).map(|q| { let r = evaluate(&q); let _ = audit::record(&audit_path, &q.command, &r); serde_json::to_string(&r).unwrap() }).unwrap_or_else(|e| serde_json::json!({"error":e.to_string()}).to_string()); if w.write_all(out.as_bytes()).await.is_err() { break } if w.write_all(b"\n").await.is_err() { break } } }
#[tokio::main] async fn main() -> std::io::Result<()> { let socket = env::var_os("AEGISGUARD_SOCKET").map(PathBuf::from).unwrap_or_else(|| PathBuf::from("/tmp/aegisguard.sock")); let _ = fs::remove_file(&socket); let listener = UnixListener::bind(&socket)?; let audit = env::var_os("AEGISGUARD_AUDIT").map(PathBuf::from).unwrap_or_else(|| PathBuf::from("aegisguard.audit.jsonl")); loop { let (stream, _) = listener.accept().await?; tokio::spawn(client(stream, audit.clone())); } }
